from typing import Any, Dict, Optional

class ConfigValidationError(ValueError):
    """Raised when a config value fails validation."""
    def __init__(self, key: str, value: Any, message: str):
        self.key = key
        self.value = value
        self.message = message
        super().__init__(f"{key}: {message} (value: {value})")

# Define the full schema based on the specification
_SCHEMA: dict[str, dict] = {
    "queue_url": {
        "type": "string",
        "default": "redis://localhost:6379/0",
        "env_var": "CELERY_QUEUE_URL",
        "validation": {"non-empty string"},
        "description": "URL of the message queue"
    },
    "concurrency": {
        "type": "int",
        "default": 3,
        "env_var": "CELERY_CONCURRENCY",
        "validation": {"int in range [1, 32]"},
        "description": "Number of concurrent workers; must be 1-32"
    },
    "max_retries": {
        "type": "int",
        "default": 8,
        "env_var": "CELERY_MAX_RETRIES",
        "validation": {"int in range [0, 20]"},
        "description": "Maximum retry attempts per job; must be 0-20"
    },
    "retry_backoff_seconds": {
        "type": "int",
        "default": 1,
        "env_var": "CELERY_RETRY_BACKOFF",
        "validation": {"int in range [1, 300]"},
        "description": "Seconds to wait between retries; must be 1-300"
    },
    "job_timeout": {
        "type": "int",
        "default": 300,
        "env_var": "CELERY_JOB_TIMEOUT",
        "validation": {"int in range [1, 3600]"},
        "description": "Job execution timeout in seconds; must be 1-3600"
    },
    "log_level": {
        "type": "enum",
        "default": "INFO",
        "env_var": "CELERY_LOG_LEVEL",
        "validation": {"one of ['DEBUG', 'INFO', 'WARN']"},
        "description": "Logging verbosity; one of ['DEBUG', 'INFO', 'WARN']"
    },
    "dead_letter_queue": {
        "type": "bool",
        "default": True,
        "env_var": "CELERY_DEAD_LETTER",
        "validation": {"bool"},
        "description": "Route failed jobs to dead letter queue"
    },
    "heartbeat_interval": {
        "type": "int",
        "default": 60,
        "env_var": "CELERY_HEARTBEAT",
        "validation": {"int in range [5, 300]"},
        "description": "Worker heartbeat interval seconds; must be 5-300"
    },
    "prefetch_count": {
        "type": "int",
        "default": 10,
        "env_var": "CELERY_PREFETCH",
        "validation": {"int in range [1, 100]"},
        "description": "Number of messages to prefetch; must be 1-100"
    },
    "ack_on_failure": {
        "type": "bool",
        "default": False,
        "env_var": "CELERY_ACK_ON_FAILURE",
        "validation": {"bool"},
        "description": "Acknowledge message even on job failure"
    },
    "metrics_enabled": {
        "type": "bool",
        "default": True,
        "env_var": "CELERY_METRICS",
        "validation": {"bool"},
        "description": "Enable Prometheus metrics"
    }
}

def get_schema() -> dict:
    """Return the config schema."""
    return _SCHEMA

def load_config(
    config_file: str | None = None,
    env_vars: dict | None = None,
    cli_args: dict | None = None,
) -> dict:
    """Load and validate configuration from all sources in priority order.

    Args:
        config_file: Path to a JSON config file (optional).
        env_vars: Dict of environment variables (defaults to os.environ).
        cli_args: Dict of CLI arguments — highest priority.

    Returns:
        A dict with all config keys populated, validated, and type-coerced.

    Raises:
        ConfigValidationError: If any value fails validation.
        FileNotFoundError: If config_file is specified but does not exist.
    """
    # Initialize config with defaults
    config = {key: spec["default"] for key, spec in _SCHEMA.items()}

    # Apply CLI arguments (highest priority)
    if cli_args:
        for key, value in cli_args.items():
            if key in config:
                config[key] = value

    # Apply environment variables
    if env_vars is None:
        env_vars = os.environ
    for key, spec in _SCHEMA.items():
        env_var = spec.get("env_var")
        if env_var and env_var in env_vars:
            config[key] = env_vars[env_var]

    # Apply config file (lowest priority)
    if config_file:
        try:
            with open(config_file, "r") as f:
                file_config = json.load(f)
            for key, value in file_config.items():
                if key in config:
                    config[key] = value
        except FileNotFoundError:
            raise FileNotFoundError(f"Config file not found: {config_file}")
        except json.JSONDecodeError:
            raise ValueError(f"Invalid JSON in config file: {config_file}")

    # Validate and coerce each value
    for key, spec in _SCHEMA.items():
        value = config[key]
        try:
            config[key] = validate_value(key, value)
        except ConfigValidationError as e:
            raise ConfigValidationError(key, value, e.message) from e

    return config

def validate_value(key: str, value: Any) -> Any:
    """Validate and coerce a single value against the schema for `key`.

    Returns the coerced value.
    Raises ConfigValidationError if invalid.
    """
    spec = _SCHEMA[key]
    type_ = spec["type"]
    validation = spec.get("validation", [])

    # Coerce value to correct type
    if type_ == "int":
        try:
            coerced = int(value)
        except (ValueError, TypeError):
            raise ConfigValidationError(key, value, "Value is not an integer")
    elif type_ == "float":
        try:
            coerced = float(value)
        except (ValueError, TypeError):
            raise ConfigValidationError(key, value, "Value is not a float")
    elif type_ == "bool":
        if isinstance(value, bool):
            coerced = value
        elif isinstance(value, str):
            value = value.lower()
            if value in ["true", "yes", "on", "1"]:
                coerced = True
            elif value in ["false", "no", "off", "0"]:
                coerced = False
            else:
                raise ConfigValidationError(key, value, "Value is not a boolean")
        else:
            raise ConfigValidationError(key, value, "Value is not a boolean")
    elif type_ == "enum":
        allowed = spec.get("allowed", [])
        if not allowed:
            raise ConfigValidationError(key, value, "Enum type missing allowed values")
        if isinstance(value, str):
            value = value.upper()
        if value not in allowed:
            raise ConfigValidationError(key, value, f"Value not in allowed enum values: {allowed}")
        coerced = value
    elif type_ == "string":
        coerced = str(value)
    else:
        raise ConfigValidationError(key, value, f"Unsupported type: {type_}")

    # Validate against specific rules
    if type_ == "int":
        if not isinstance(coerced, int):
            raise ConfigValidationError(key, value, "Value is not an integer")
        if validation and "int in range [1, 32]" in validation:
            if not (1 <= coerced <= 32):
                raise ConfigValidationError(key, value, "Value is not in range [1, 32]")
        elif validation and "int in range [0, 20]" in validation:
            if not (0 <= coerced <= 20):
                raise ConfigValidationError(key, value, "Value is not in range [0, 20]")
        elif validation and "int in range [1, 300]" in validation:
            if not (1 <= coerced <= 300):
                raise ConfigValidationError(key, value, "Value is not in range [1, 300]")
        elif validation and "int in range [1, 3600]" in validation:
            if not (1 <= coerced <= 3600):
                raise ConfigValidationError(key, value, "Value is not in range [1, 3600]")
        elif validation and "int in range [5, 300]" in validation:
            if not (5 <= coerced <= 300):
                raise ConfigValidationError(key, value, "Value is not in range [5, 300]")
        elif validation and "int in range [1, 100]" in validation:
            if not (1 <= coerced <= 100):
                raise ConfigValidationError(key, value, "Value is not in range [1, 100]")
    elif type_ == "enum":
        if validation and "one of ['DEBUG', 'INFO', 'WARN']" in validation:
            if coerced not in ["DEBUG", "INFO", "WARN"]:
                raise ConfigValidationError(key, value, "Value is not one of ['DEBUG', 'INFO', 'WARN']")
    elif type_ == "bool":
        if validation and "bool" in validation:
            if not isinstance(coerced, bool):
                raise ConfigValidationError(key, value, "Value is not a boolean")
    else:
        if validation and "non-empty string" in validation:
            if not isinstance(coerced, str) or len(coerced) == 0:
                raise ConfigValidationError(key, value, "Value is not a non-empty string")

    return coerced
